scripts.李三对话.txt:
// 与李三的对话

	If ($Event == 310) @Event310;
	If ($Event == 320) @Event320;
	If ($Event == 360) @Event360;
	
	Return;
	
@Event310:	
	Say("李三：我一直在等二位呢，不知两位要俺帮什么忙？只要李三能做到，二位尽管吩咐。", 70);
	Say("独孤剑：有人欲对华山顾大侠不利，我们要赶上华山通知顾大侠。可是山门弟子不肯放行，我们不便硬闯，所以想另寻一条上山之路，听说你对华山很熟悉，不知能否找到这么一条路？", 1);
	Say("李三：华山顾大侠乃是响当当的英雄，当年他一气杀掉十三名金国高手，俺李三就佩服这样的好汉！因为金人一直想除掉他，所以华山的防范很严密，也难怪你上不了山。俺倒是知道一条上山的小路，我这就带你们去！", 70);
	Say("独孤剑：多谢！", 2);
	SetNpcKind("李三", 3);
	SetNpcRelation("李三", 2);
	SetNpcRelation("张琳心", 0);
	Assign($Event, 320);
	Memo("两人来到石塘镇，找到李三，三人一同前往华山。");
	SetMapTrap(1, "trap01.txt");
	Return;
	
@Event320:
	Say("李三：咱们这就走吧！", 70);
	Return; 	
	
@Event360:
	Say("李三：没想到顾大侠竟然就这样不明不白地死了，俺瞧那个林海肯定不是什么好东西！连自己师兄都杀的人简直猪狗不如！", 70);
	Return;

scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 280) @Event280;
	If ($Event == 290) @Event290;
	If ($Event == 300) @Event300;
	If ($Event == 310) @Event310;
	If ($Event == 320) @Event320;
	If ($Event == 360) @Event360;
	
	Return;

@Event280:
	Say("张琳心：这间房子的主人好像不在家。", 21);
	Return;
	
@Event290:
	Say("张琳心：这间房子的主人好像不在家。", 21);
	Return;
	
@Event300:
	Say("张琳心：我们快去长安找李三吧。", 21);
	Return;	
	
@Event310:
	Say("张琳心：那不是李三吗？", 21);
	Return;	
	
@Event320:
	Say("张琳心：事不宜迟，我们赶快上山，再晚可能就来不及了。", 21);
	Return; 	
	
@Event360:
	Say("张琳心：我们快点去长安吧。", 21);
	Return;

traps.trap01.txt:
// 切换到map044石塘镇

	If ($Event == 310) @Event310;
	
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map044_石塘镇.map");
	LoadNpc("map044.npc");
	LoadObj("map044.obj");
	SetPlayerPos(16, 23);
	SetPlayerDir(1);
	FadeIn();
	Return;
	
@Event310:
	Return;
